8	pub struct PrintGitHubDiagnostic<'fmt, D: ?Sized>(pub &'fmt D);
9	
10	impl<D: AsDiagnostic + ?Sized> fmt::Display for PrintGitHubDiagnostic<'_, D> {
11	    fn fmt(&self, fmt: &mut fmt::Formatter<'_>) -> io::Result<()> {
12	        let diagnostic = self.0.as_diagnostic();
13	        let location = diagnostic.location();
14	
15	        // Docs:
16	        // https://docs.github.com/en/actions/using-workflows/workflow-commands-for-github-actions
17	
18	        let Some(span) = location.span else {
19	            return Ok(());
20	        };
21	        let Some(source_code) = location.source_code else {
22	            return Ok(());
23	        };
24	
25	        let file_name_unescaped = match &location.resource {
26	            Some(Resource::File(file)) => file,
27	            _ => return Ok(()),
28	        };
29	
30	        let source = SourceFile::new(source_code);
31	        let start = source.location(span.start())?;
32	        let end = source.location(span.end())?;
33	
34	        let command = match diagnostic.severity() {
35	            Severity::Error | Severity::Fatal => "error",
36	            Severity::Warning => "warning",
37	            Severity::Hint | Severity::Information => "notice",
38	        };
39	
40	        let message = {
41	            let mut message = MarkupBuf::default();
42	            let mut fmt = fmt::Formatter::new(&mut message);
43	            fmt.write_markup(markup!({ PrintDiagnosticMessage(diagnostic) }))?;
44	            markup_to_string(&message)
45	        };
46	
47	        let title = {
48	            diagnostic
49	                .category()
50	                .map(|category| category.name())
51	                .unwrap_or_default()
52	        };
53	
54	        fmt.write_str(
55	            format! {
56	                "::{} title={},file={},line={},endLine={},col={},endColumn={}::{}",
57	                command, // constant, doesn't need escaping
58	                title, // the diagnostic category
59	                escape_property(file_name_unescaped),
60	                start.line_number, // integer, doesn't need escaping
61	                end.line_number, // integer, doesn't need escaping
62	                start.column_number, // integer, doesn't need escaping
63	                end.column_number, // integer, doesn't need escaping
64	                message.map_or_else(String::new, escape_data),
65	            }
66	            .as_str(),
67	        )?;
68	
69	        Ok(())
70	    }
71	}
