75	impl<D: Diagnostic + ?Sized> fmt::Display for PrintDiagnosticMessage<'_, D> {
76	    fn fmt(&self, fmt: &mut fmt::Formatter<'_>) -> io::Result<()> {
77	        let Self(diagnostic) = *self;
78	        diagnostic.message(fmt)?;
79	        Ok(())
80	    }
81	}
